const healthResp = $('Fetch Week Health Data').first().json;
const issuesResp = $('Fetch GitHub Issues').first().json;
const healthBody = healthResp.body || healthResp || [];
const records = Array.isArray(healthBody) ? healthBody : [];
const issuesBody = issuesResp.body || issuesResp || {};
const issues = issuesBody.items || [];
const today = new Date().toISOString().split('T')[0];
const appData = {};
// Live product set for OS rollup purposes (2026-07-06): gutted, merciless, onalert retired from the control plane.
// plinth and full-time added (own Vercel projects + own Supabase). Neither exposes a product-truth endpoint yet, [RETIRED 2026-08-11: Plinth was renamed Legibility 2026-08-07 and then retired; it has zero customers and no live Stripe path.]
// so there is no per-product config to wire here beyond the app_name key used to match product_health rows and
// GitHub repo name. TODO: once plinth/full-time have health-check ingestion wired into product_health, their
// checks/healthy/down/broken counts will populate here automatically; until then they will show checks=0, score=100 (default).
const appNames = ['mm-ctrl','fractionl-circle','fractionl-pulse','plinth','full-time','mindmaker'];
for (const name of appNames) {
  appData[name] = { checks: 0, healthy: 0, down: 0, broken: 0, lastCommitDays: 0, openIssues: 0 };
}
for (const r of records) {
  const name = r.app_name;
  if (!appData[name]) continue;
  appData[name].checks++;
  if (r.system_status === 'healthy') appData[name].healthy++;
  else if (r.system_status === 'down') appData[name].down++;
  else appData[name].broken++;
  if (appData[name].checks === 1) {
    appData[name].lastCommitDays = r.days_since_last_commit;
    appData[name].openIssues = r.open_issues;
  }
}
for (const issue of issues) {
  const repoName = (issue.repository_url || '').split('/').pop();
  if (appData[repoName]) appData[repoName].openIssues++;
}
let rankings = [];
for (const [name, data] of Object.entries(appData)) {
  let score = 100;
  if (data.checks > 0) score = Math.round((data.healthy / data.checks) * 60);
  if (data.lastCommitDays > 14) score -= 20;
  else if (data.lastCommitDays > 7) score -= 10;
  if (data.down > 0) score -= data.down * 15;
  if (data.broken > 0) score -= data.broken * 10;
  score = Math.max(0, Math.min(100, score));
  rankings.push({ name, score, ...data });
}
rankings.sort((a, b) => a.score - b.score);
let report = 'PRIYA WEEKLY ROLLUP // ' + today + '\n\nPRODUCTION READINESS:\n';
for (const r of rankings) {
  const bar = r.score >= 80 ? 'READY' : r.score >= 50 ? 'NEEDS WORK' : 'AT RISK';
  report += '  ' + r.name + ': ' + r.score + '/100 [' + bar + ']';
  if (r.checks > 0) report += ' (uptime: ' + Math.round(r.healthy/r.checks*100) + '%)';
  report += '\n';
}
report += '\nTOP ACTIONS:\n';
let actions = [];
for (const r of rankings) {
  if (r.down > 0) actions.push('Fix ' + r.name + ' downtime');
  if (r.broken > 0) actions.push('Fix ' + r.name + ' errors');
  if (r.lastCommitDays > 10) actions.push('Ship ' + r.name + ' (stalling at ' + r.lastCommitDays + 'd)');
}
if (actions.length === 0) actions.push('All apps healthy. Ship features.');
for (let i = 0; i < Math.min(3, actions.length); i++) {
  report += '  ' + (i+1) + '. ' + actions[i] + '\n';
}
report += '\n' + records.length + ' health checks, ' + issues.length + ' open issues this week.';
const worstApp = rankings[0] || { name: 'none', score: 100 };
return [{ json: { report_text: report, telegram_text: report, today, worst_app: worstApp.name, worst_score: worstApp.score, total_checks: records.length, total_issues: issues.length } }];

// Build Audit payload for Priya weekly product rollup
const d = $input.first().json;
const total = d.products_total || d.products || 0;
const issuesWeek = d.issues_total || d.issues || 0;
const week = d.week_of || new Date().toISOString().slice(0, 10);

return [{
  json: {
    audit_payload: {
      actor: 'priya',
      event_type: 'product-rollup-weekly',
      display_message: `Priya weekly product rollup (week of ${week}): ${total} products tracked, ${issuesWeek} issues this week.`,
      details: JSON.stringify({ products_total: total, issues_total: issuesWeek, week_of: week })
    }
  }
}];

const goalsRaw = $('Read Weekly Goals').first().json;
const goalsArr = Array.isArray(goalsRaw) ? goalsRaw : (goalsRaw.data || [goalsRaw]);
const goals = goalsArr.filter(g => g && g.id);
const bwr = $('Build Weekly Report').first().json || {};

function pickGoalId(text) {
  if (!text || !goals.length) return null;
  const hay = String(text).toLowerCase();
  let best = null, bestLen = 0;
  for (const g of goals) {
    for (const c of [g.title, g.current].filter(Boolean)) {
      for (const tok of String(c).toLowerCase().split(/[^a-z0-9]+/).filter(t => t.length >= 4)) {
        if (hay.includes(tok) && tok.length > bestLen) { best = g.id; bestLen = tok.length; }
      }
    }
  }
  return best;
}

const text = (bwr.report_text || '') + ' product health weekly rollup ' + (bwr.worst_app||'');
const weekly_goal_id = pickGoalId(text);
return $input.all().map(item => ({ json: { ...(item.json||{}), weekly_goal_id } }));
